/**
 * Demo data: one user, two agents with different policies, and three weeks of realistic
 * history (completed purchases, a denied gift card, a blocked wrong-merchant charge, a refund,
 * a trust suggestion, and live pending approvals). Generated by running the real purchase
 * flow against the mock issuer on a simulated clock, so everything is consistent.
 *
 *   npm run db:seed            (uses DATABASE_URL)
 */
import "dotenv/config";
import { createDb } from "@agent-wallet/db";
import { MockCardIssuer } from "../src/issuer/mock";
import { silentLogger } from "../src/logger";
import { ConsoleEmailSender, ConsolePushSender } from "../src/notify/senders";
import { parsePolicy } from "../src/policy/schema";
import { templateRules } from "../src/policy/templates";
import { MemoryRateLimiter } from "../src/security";
import { createWallet, type AuthedAgent } from "../src/wallet/index";

const DEMO_EMAIL = process.env["SEED_EMAIL"] ?? "demo@agentwallet.dev";
const DAY = 86_400_000;

async function main() {
  const db = createDb();
  const existing = await db.user.findUnique({ where: { email: DEMO_EMAIL } });
  if (existing) {
    console.log(`Demo user ${DEMO_EMAIL} already exists; nothing to do. (Reset with: npm run db:reset)`);
    await db.$disconnect();
    return;
  }

  const realNow = new Date();
  // Noon in Los Angeles, 21 days ago.
  const clock = { now: new Date(Math.floor((realNow.getTime() - 21 * DAY) / DAY) * DAY + 19 * 3_600_000) };
  const issuer = new MockCardIssuer(process.env["MOCK_ISSUER_WEBHOOK_SECRET"] ?? "mock_webhook_secret", () => clock.now);
  const wallet = createWallet({
    db,
    issuer,
    logger: silentLogger,
    email: new ConsoleEmailSender(silentLogger),
    push: new ConsolePushSender(silentLogger),
    agentRateLimiter: new MemoryRateLimiter(10_000, 60_000),
    now: () => clock.now,
    config: { appUrl: process.env["APP_URL"] ?? "http://localhost:3000", trustMinStreak: 5 },
  });
  const deliver = async (body: string, headers: Headers) => {
    const r = await wallet.issuerEvents.handleWebhook(body, headers);
    return { status: r.status, body: r.body };
  };

  const user = await wallet.owner.ensureUser(DEMO_EMAIL, { name: "Demo User", timezone: "America/Los_Angeles" });

  const groceryRules = templateRules("groceries_under_50", "America/Los_Angeles");
  const grocery = await wallet.owner.createAgent(user.id, { name: "Grocery Bot (Claude)", rules: groceryRules });
  const office = await wallet.owner.createAgent(user.id, {
    name: "Office Supplies Agent",
    rules: parsePolicy({
      merchants: { mode: "blocklist", deny_domains: ["temu.com"] },
      categories: { allow: ["office", "electronics", "household"] },
      limits: { per_order_total: 150, per_day: 200, per_week: 400, per_month: 800, max_quantity_per_item: 20, max_orders_per_day: 5 },
      approval: { always: false, require_if_total_over: 60, require_for_new_merchant: true },
      schedule: { timezone: "America/Los_Angeles", allowed_hours: null },
      currency: "USD",
    }),
  });
  const gAgent = (await wallet.owner.authenticateAgent(grocery.apiKey)) as AuthedAgent;
  const oAgent = (await wallet.owner.authenticateAgent(office.apiKey)) as AuthedAgent;

  const cart = (merchant: string, name: string, items: { name: string; category?: string; unit_price: number; quantity: number; url?: string }[], tax = 0, shipping = 0, reasoning = "Restocking what the user asked for") => {
    const subtotal = Math.round(items.reduce((s, i) => s + i.unit_price * i.quantity, 0) * 100) / 100;
    return { merchant_domain: merchant, merchant_name: name, items, subtotal, tax, shipping, total: Math.round((subtotal + tax + shipping) * 100) / 100, currency: "USD", reasoning };
  };

  /** Request → approve if needed → issue → charge. */
  async function buy(agent: AuthedAgent, c: ReturnType<typeof cart>, charge: { merchant: string; mcc: string } | null) {
    let r = await wallet.purchases.requestPurchase(agent, c);
    if (r.status === "pending_approval") {
      clock.now = new Date(clock.now.getTime() + 4 * 60_000);
      await wallet.owner.decideApproval(user.id, r.id, "approved", r.cart_hash);
    }
    if (r.status === "denied") return r;
    r = await wallet.purchases.getPurchaseStatus(agent, r.id);
    if (charge) {
      const cred = await db.issuedCredential.findFirstOrThrow({ where: { purchaseRequestId: r.id } });
      await issuer.simulateCharge({ providerCardId: cred.providerCardId, amountCents: Math.round(c.total * 100), merchant: { name: charge.merchant, mcc: charge.mcc, domain: null, country: "US" }, deliver });
      await wallet.purchases.reportPurchaseResult(agent, r.id, { success: true, order_reference: `ORD-${Math.floor(Math.random() * 1e6)}` });
    }
    return r;
  }
  const nextDay = (hours = 0) => (clock.now = new Date(clock.now.getTime() + DAY + hours * 3_600_000));

  const groceryRuns = [
    [{ name: "Organic bananas", unit_price: 3.49, quantity: 2 }, { name: "Whole milk 1 gal", unit_price: 4.29, quantity: 1 }, { name: "Eggs, dozen", unit_price: 5.99, quantity: 1 }],
    [{ name: "Paper towels 6-pack", unit_price: 12.99, quantity: 1 }, { name: "Dish soap", unit_price: 3.79, quantity: 2 }],
    [{ name: "Oat milk", unit_price: 4.49, quantity: 2 }, { name: "Granola", unit_price: 6.99, quantity: 1 }, { name: "Blueberries", unit_price: 4.99, quantity: 2 }],
    [{ name: "Chicken breast 2 lb", unit_price: 11.99, quantity: 1 }, { name: "Brown rice", unit_price: 3.49, quantity: 1 }, { name: "Broccoli", unit_price: 2.49, quantity: 2 }],
    [{ name: "Coffee beans 12oz", unit_price: 13.99, quantity: 1 }, { name: "Bread", unit_price: 4.49, quantity: 1 }],
    [{ name: "Laundry detergent", unit_price: 15.99, quantity: 1 }, { name: "Trash bags", unit_price: 9.99, quantity: 1 }],
    [{ name: "Salmon fillet", unit_price: 14.99, quantity: 1 }, { name: "Spinach", unit_price: 3.99, quantity: 1 }, { name: "Lemons", unit_price: 0.79, quantity: 4 }],
    [{ name: "Peanut butter", unit_price: 4.99, quantity: 1 }, { name: "Strawberries", unit_price: 4.49, quantity: 2 }, { name: "Yogurt", unit_price: 1.29, quantity: 6 }],
    [{ name: "Olive oil", unit_price: 11.99, quantity: 1 }, { name: "Pasta", unit_price: 1.99, quantity: 3 }, { name: "Tomatoes", unit_price: 2.99, quantity: 2 }],
    [{ name: "Cereal", unit_price: 4.99, quantity: 2 }, { name: "Bananas", unit_price: 0.29, quantity: 6 }, { name: "Cheese", unit_price: 6.49, quantity: 1 }],
  ];

  let refundTarget: string | null = null;
  for (const [i, items] of groceryRuns.entries()) {
    const store = i % 3 === 2 ? ["target.com", "Target", "TARGET 00012345"] : ["amazon.com", "Amazon", "AMZN Mktp US"];
    const r = await buy(gAgent, cart(store[0]!, store[1]!, items, 1.2, 0), { merchant: store[2]!, mcc: "5411" });
    if (i === 0) refundTarget = r.id;
    nextDay(i % 2);

    if (i === 4) {
      // A gift card slipped into a cart: denied outright.
      await wallet.purchases.requestPurchase(gAgent, cart("amazon.com", "Amazon", [{ name: "Apples", unit_price: 4.99, quantity: 1 }, { name: "Amazon.com eGift Card", unit_price: 50, quantity: 1 }], 0, 0, "User mentioned a birthday"));
    }
    if (i === 1) {
      // Card used at the wrong merchant: declined at the money, logged as a security event.
      const r2 = await wallet.purchases.requestPurchase(gAgent, cart("amazon.com", "Amazon", [{ name: "Avocado", unit_price: 1.99, quantity: 4 }]));
      if (r2.status === "pending_approval") await wallet.owner.decideApproval(user.id, r2.id, "approved", r2.cart_hash);
      await wallet.purchases.getPurchaseStatus(gAgent, r2.id);
      const cred = await db.issuedCredential.findFirstOrThrow({ where: { purchaseRequestId: r2.id } });
      await issuer.simulateCharge({ providerCardId: cred.providerCardId, amountCents: 796, merchant: { name: "QUICKCASH ELECTRONICS", mcc: "5732", domain: null, country: "US" }, deliver });
      await wallet.purchases.cancelPurchase(gAgent, r2.id, "checkout redirected to an unexpected payment page");
    }
  }

  // A refund on one grocery order (budget restored).
  if (refundTarget) {
    const cred = await db.issuedCredential.findFirstOrThrow({ where: { purchaseRequestId: refundTarget } });
    await issuer.simulateRefund({ providerCardId: cred.providerCardId, amountCents: 599, merchant: { name: "AMZN Mktp US", mcc: "5411", domain: null, country: "US" }, deliver });
  }

  // Office agent history.
  clock.now = new Date(realNow.getTime() - 6 * DAY);
  await buy(oAgent, cart("staples.com", "Staples", [{ name: "Printer paper, 5 reams", unit_price: 42.99, quantity: 1 }, { name: "Sticky notes", unit_price: 6.49, quantity: 2 }], 4.4, 0), { merchant: "STAPLES 0123", mcc: "5943" });
  clock.now = new Date(realNow.getTime() - 3 * DAY);
  await buy(oAgent, cart("amazon.com", "Amazon", [{ name: "USB-C charger cable", unit_price: 14.99, quantity: 2 }], 2.7, 0), { merchant: "AMZN Mktp US", mcc: "5732" });
  await wallet.purchases.requestPurchase(oAgent, cart("temu.com", "Temu", [{ name: "Desk organizer", unit_price: 8.99, quantity: 1 }]));

  // Live items for the dashboard: pending approvals right now.
  clock.now = new Date(realNow.getTime() - 20 * 60_000);
  await wallet.purchases.requestPurchase(
    oAgent,
    cart("bestbuy.com", "Best Buy", [{ name: "27-inch 4K monitor", unit_price: 129.99, quantity: 1, url: "https://www.bestbuy.com/site/27-4k-monitor/123.p" }], 11.7, 0, "User asked for a second monitor for the home office, under $150."),
  );
  clock.now = new Date(realNow.getTime() - 5 * 60_000);
  await wallet.purchases.requestPurchase(
    gAgent,
    cart("amazon.com", "Amazon", [{ name: "Organic bananas", unit_price: 3.49, quantity: 2 }, { name: "Mystery snack box", category: "groceries", unit_price: 18.99, quantity: 1 }], 1.6, 0, "Weekly restock; the snack box was on sale."),
  );

  await wallet.trust.refresh(gAgent.id);
  await db.$disconnect();

  console.log(`
Seeded demo data for ${DEMO_EMAIL}

  Agent: ${grocery.agent.name}
    API key: ${grocery.apiKey}
  Agent: ${office.agent.name}
    API key: ${office.apiKey}

These keys are shown only now (only hashes are stored). Rotate them from the dashboard if lost.
`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
